node --input-type=module <<'JS'
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {readFileSync,existsSync} from 'node:fs';
const {fingerprint:f}=JSON.parse(readFileSync('fixtures/react-parity/runtime/evidence.json')).source;
const sha=value=>createHash('sha256').update(value).digest('hex');
const paths=[...new Set(execFileSync('git',['ls-files','-z','--cached','--others','--exclude-standard','--',...f.pathspecs],{encoding:'utf8'}).split('\0').filter(Boolean))].filter(path=>!f.excludedPaths.includes(path)&&existsSync(path)).sort();
const actual=sha(paths.map(path=>sha(readFileSync(path))+'  '+path+'\n').join(''));
if(paths.length!==f.fileCount||actual!==f.sha256) throw new Error('Source fingerprint mismatch');
console.log(paths.length+' files: '+actual);
JS
